  insert into public.course_items (course_id, kind, position, title, content) select cid, 'topic', 5, $j$2.1 Alcohol, Tobacco, Vaping and Drugs$j$, $j${"readings": [{"title": "Proverbs 20 (King James Version)", "url": "/portal/bible/Proverbs/20"}], "body": "Substances change how the brain and body work. Alcohol slows the brain, hurts judgment and coordination, and is illegal for anyone under twenty one. Tobacco and vaping products contain nicotine, which is highly addictive and can harm the developing teen brain, affecting attention, learning and mood. In the United States and in Florida, the legal age to buy tobacco and nicotine products is twenty one. Marijuana can affect memory and learning and is not legal for teens. Misusing prescription medicine, such as opioids or stimulants, is dangerous. Pills bought from friends or online can be counterfeit and may contain fentanyl, a very strong drug that can cause death in a tiny amount.\n\nAddiction is a brain condition in which a person feels unable to stop using even when it causes harm. Warning signs include needing more of a substance, failed attempts to quit, and loss of interest in other things. Treatment and support work. Proverbs 20:1 says, Wine is a mocker, strong drink is raging: and whosoever is deceived thereby is not wise. Ephesians 5:18 says, be not drunk with wine, wherein is excess; but be filled with the Spirit.\n\nRefusal skills help you say no: say no firmly, give a reason, suggest something else, and leave. Proverbs 1:10 says, My son, if sinners entice thee, consent thou not.\n\nWorked example: a friend offers a vape. Say, No thanks, I am good, and move to another group. Common mistake: believing that vaping is harmless because it has no smoke.\n\nYour task: (1) List three harms of nicotine or alcohol. (2) Explain why pills from friends are dangerous. (3) Write a refusal line and a trusted adult you could tell.\n\nFlorida standards: HE.912.C.1, HE.912.C.2, HE.912.B.4, HE.912.B.5.", "video": "", "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "HE.912.C.1, HE.912.C.2, HE.912.B.4, HE.912.B.5", "script": "Welcome back. Listen, the choices you make about substances can shape your future for good or for harm.\n\nSubstances change how the brain and body work. Alcohol slows the brain and hurts judgment, and it is illegal under twenty one. Tobacco and vaping products contain nicotine, which is highly addictive and can harm the teen brain. The legal age to buy them is twenty one. Misusing prescription medicine is dangerous, and pills from friends or online can be counterfeit and may contain fentanyl, which can kill in a tiny amount.\n\nNow watch this. Addiction is a brain condition where a person cannot stop even when it causes harm. Warning signs are needing more, failed attempts to quit and losing interest in other things. Help and treatment work.\n\nProverbs 20:1 says, Wine is a mocker, strong drink is raging. Proverbs 1:10 says, My son, if sinners entice thee, consent thou not.\n\nRefusal skills: say no firmly, give a reason, suggest something else and leave.\n\nYour task is to list three harms, explain pill danger and write a refusal line. Take the four question check. Excellence, Faith, Purpose. I will see you in the next lesson."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'topic' and title = $j$2.1 Alcohol, Tobacco, Vaping and Drugs$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'topic', 6, $j$2.2 Disease Prevention and Immunity$j$, $j${"readings": [{"title": "Proverbs 22 (King James Version)", "url": "/portal/bible/Proverbs/22"}], "body": "Diseases are either communicable, spread from person to person, or noncommunicable, such as heart disease and diabetes, which are not spread. Pathogens are germs that cause communicable disease: bacteria, viruses, fungi and parasites. Germs spread by touch, droplets in the air, contaminated food or water, insect bites and body fluids.\n\nYour body defends itself with skin, mucus, white blood cells and antibodies. Vaccines train the immune system to recognize a germ before you meet it, and they have prevented many serious diseases. Talk with a parent and a doctor about which vaccines you need. Antibiotics treat bacterial infections, not viral ones such as colds and flu, and using them wrongly makes germs resistant.\n\nPrevent illness by washing hands, covering coughs, staying home when sick, not sharing drinks or personal items, handling food safely, getting checkups and sleeping well. Infections that spread through sexual contact, including HIV, are avoided most surely by abstinence until marriage and faithfulness in marriage. HIV can also spread through shared needles, so never share needles. Anyone who has questions or symptoms should talk with a parent or doctor. Proverbs 22:3 says, A prudent man foreseeth the evil, and hideth himself: but the simple pass on, and are punished.\n\nWorked example: a classmate has the flu. Wash your hands, avoid sharing cups, and get rest if you feel ill. Common mistake: taking antibiotics for a cold. They do not work on viruses.\n\nYour task: (1) Define communicable and noncommunicable disease and give an example of each. (2) List four ways to prevent infection. (3) Explain how vaccines work.\n\nFlorida standards: HE.912.C.1, HE.912.B.7, HE.912.P.8.", "video": "", "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "HE.912.C.1, HE.912.B.7, HE.912.P.8", "script": "Welcome back. Listen, prevention is wise. Proverbs 22:3 says, A prudent man foreseeth the evil, and hideth himself.\n\nDiseases are communicable, spread from person to person, or noncommunicable, like heart disease and diabetes. Germs called pathogens, such as bacteria, viruses, fungi and parasites, cause communicable disease. They spread by touch, droplets in the air, contaminated food or water, insect bites and body fluids.\n\nNow watch this. Your body defends itself with skin, mucus, white blood cells and antibodies. Vaccines train your immune system to recognize a germ before you meet it. Talk with a parent and a doctor about the vaccines you need. Antibiotics treat bacteria, not viruses like colds and flu.\n\nTo prevent illness, wash your hands, cover coughs, stay home when sick, do not share drinks, handle food safely, get checkups and sleep well. Infections spread through sexual contact, including HIV, are avoided most surely by abstinence until marriage and faithfulness in marriage. HIV can also spread through shared needles, so never share needles. Ask a parent or doctor if you have questions.\n\nYour task is to define the two kinds of disease, list four prevention steps and explain vaccines. Take the four question check. Excellence, Faith, Purpose. I will see you in the next lesson."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'topic' and title = $j$2.2 Disease Prevention and Immunity$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'topic', 7, $j$2.3 Safety, Injury Prevention and First Aid$j$, $j${"readings": [{"title": "Proverbs 27 (King James Version)", "url": "/portal/bible/Proverbs/27"}], "body": "Injuries are a leading cause of death for teens, and many can be prevented. Wear a seat belt every time. Never drive distracted, impaired or drowsy. Wear helmets for biking, skating and contact sports. Learn to swim and never swim alone. Stay away from weapons and tell an adult if you see one. Test smoke alarms, know two exits from every room and never leave cooking unattended. Proverbs 27:12 says, A prudent man foreseeth the evil, and hideth himself.\n\nIn an emergency, stay calm, make sure the scene is safe, and call 911. Give your location, say what happened and stay on the line. For bleeding, apply firm direct pressure with a clean cloth and do not remove it. For a burn, cool it with running water for several minutes. For choking in an adult, give abdominal thrusts. A suspected concussion needs a medical visit, so do not return to play. For poison, call the Poison Help line.\n\nCardiopulmonary resuscitation, or CPR, can save a life when a heart stops. Hands only CPR for an adult who collapses: call 911, push hard and fast in the center of the chest at 100 to 120 compressions per minute, and keep going until help arrives. If an automated external defibrillator, or AED, is nearby, turn it on and follow its voice prompts. Florida schools teach CPR awareness, and a certified class from a recognized organization gives hands on practice.\n\nWorked example: a person collapses and is not breathing. Shout for help, call 911, start compressions, and send someone for the AED. Common mistake: waiting to see if the person wakes up.\n\nYour task: (1) List five safety habits. (2) Write the steps of Hands only CPR. (3) Describe what to tell the 911 operator.\n\nFlorida standards: HE.912.C.1, HE.912.B.7, HE.912.P.8.", "video": "", "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "HE.912.C.1, HE.912.B.7, HE.912.P.8", "script": "Welcome back. Listen, one of the best things you can do is to be prepared. Proverbs 27:12 says, A prudent man foreseeth the evil.\n\nMany injuries can be prevented. Wear a seat belt every time. Never drive distracted, impaired or drowsy. Wear a helmet for biking, skating and contact sports. Learn to swim and never swim alone. Know two exits from every room.\n\nNow watch this. In an emergency, stay calm, make sure the scene is safe and call 911. Give your location, say what happened and stay on the line. For bleeding, press firmly with a clean cloth. For a burn, cool it with running water. For a suspected concussion, see a doctor.\n\nCPR can save a life. For an adult who collapses, call 911. Push hard and fast in the center of the chest, one hundred to one hundred twenty times a minute, and keep going until help arrives. If an AED is nearby, turn it on and follow the voice prompts. A certified class gives you hands on practice.\n\nYour task is to list five safety habits, write the steps of Hands only CPR and describe what to tell the operator. Take the four question check. Excellence, Faith, Purpose. I will see you in the next lesson."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'topic' and title = $j$2.3 Safety, Injury Prevention and First Aid$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'topic', 8, $j$2.4 Violence, Bullying and Online Safety$j$, $j${"readings": [{"title": "Ephesians 4 (King James Version)", "url": "/portal/bible/Ephesians/4"}], "body": "Violence and bullying harm health. Bullying is repeated unwanted behavior meant to hurt, and it can be physical, verbal, social or online. Cyberbullying uses phones and the internet. Bullying and harassment can lead to anxiety, poor sleep and trouble at school. Ephesians 4:32 says, And be ye kind one to another, tenderhearted, forgiving one another, even as God for Christ's sake hath forgiven you.\n\nIf you are bullied: stay calm, do not retaliate, save messages, block the account, and tell a trusted adult. If you see bullying, be an upstander: stand with the person, do not join in, and report it. Florida law requires schools to have policies against bullying and harassment.\n\nOnline safety: keep your accounts private, use strong passwords, never share personal information, do not meet strangers from the internet, and think before you post because content can last. Sending or asking for private pictures is dangerous, can be illegal for minors and can be used to hurt you. Anyone who pressures you online should be reported to a parent, school or law enforcement. Predators sometimes pretend to be peers. Talk to a trusted adult if something feels wrong.\n\nDating violence is controlling or harming a partner. Warning signs are jealousy, isolating you, checking your phone, threats, pushing or humiliating you. Love does not hurt or control. Teens can get help from a trusted adult, a counselor, or the National Domestic Violence Hotline.\n\nWorked example: a classmate is mocked in a group chat. Do not reply with a joke. Send a kind private message, save the evidence and report it. Common mistake: staying silent because it is not about you.\n\nYour task: (1) Define bullying and cyberbullying. (2) List three online safety rules. (3) Write two signs of an unhealthy relationship and who you would tell.\n\nFlorida standards: HE.912.C.2, HE.912.B.4, HE.912.B.5, HE.912.P.8.", "video": "", "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "HE.912.C.2, HE.912.B.4, HE.912.B.5, HE.912.P.8", "script": "Welcome back. Listen, every person is made in the image of God and deserves to be safe and treated with respect.\n\nBullying is repeated unwanted behavior meant to hurt. It can be physical, verbal, social or online. Cyberbullying happens through phones and the internet. It can lead to anxiety, poor sleep and trouble at school. Ephesians 4:32 says, Be ye kind one to another, tenderhearted, forgiving one another.\n\nNow watch this. If you are bullied, stay calm, do not retaliate, save the messages, block the account and tell a trusted adult. If you see bullying, be an upstander. Stand with the person, do not join in and report it.\n\nOnline, keep accounts private, use strong passwords, never share personal information and never meet strangers from the internet. Think before you post. Sending or asking for private pictures is dangerous and can be illegal for minors. Predators sometimes pretend to be peers.\n\nDating violence is controlling or harming a partner. Warning signs are jealousy, isolating you, threats and humiliation. Love does not hurt or control.\n\nYour task is to define bullying, list three online rules and name two signs of an unhealthy relationship. Take the four question check. Excellence, Faith, Purpose. I will see you in the next lesson."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'topic' and title = $j$2.4 Violence, Bullying and Online Safety$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'assessment', 2, $j$Assessment 2: Risk and Prevention$j$, $j${"prompt": "Write a report of at least 250 words on prevention and safety. Use complete sentences and label each part. Do not include private details about yourself or others. Proverbs 22:3 says, A prudent man foreseeth the evil, and hideth himself: but the simple pass on, and are punished.\n\nPart 1: Explain three harms of alcohol, nicotine or other drugs and write a refusal plan with a trusted adult you would tell.\nPart 2: Explain the difference between communicable and noncommunicable disease and describe four ways to prevent infection.\nPart 3: Write a home safety and emergency plan, including what to say when you call 911 and the steps of Hands only CPR.\nPart 4: Describe bullying, cyberbullying and three online safety rules, and tell how an upstander helps.\nPart 5: Explain how Scripture encourages prudence, kindness and protection of others.", "rubric": "100 points. Part 1: 20 points. Part 2: 20 points. Part 3: 25 points. Part 4: 20 points. Part 5: 10 points. Complete sentences and conventions: 5 points. A score of 70 or above is passing."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'assessment' and title = $j$Assessment 2: Risk and Prevention$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'discussion', 2, $j$Discussion 2: Choosing Prudence$j$, $j${"prompt": "Write a post of at least 120 words that (1) describes one risk teens face today, (2) explains a refusal or safety skill that helps, (3) tells how you can support a friend who feels pressured, and (4) connects your answer to Proverbs 22:3 or Proverbs 1:10. Then write a respectful reply of at least 40 words to another student's post, or answer this question: Why is it wise to prepare before an emergency happens? Do not share private details about yourself or others."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'discussion' and title = $j$Discussion 2: Choosing Prudence$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 6, $j$Check 2.1: Alcohol, Tobacco, Vaping and Drugs$j$, $j${"questions": [{"q": "The legal age to buy tobacco and nicotine products is:", "options": ["Fourteen", "Sixteen", "Eighteen", "Twenty one"]}, {"q": "Nicotine is harmful to teens because it is:", "options": ["Harmless", "Highly addictive and affects the developing brain", "Good for focus", "A vitamin"]}, {"q": "Pills bought from friends or online may contain:", "options": ["Safe medicine", "Only vitamins", "Candy", "Fentanyl, a deadly drug"]}, {"q": "A good refusal skill is to:", "options": ["Laugh it off", "Say no firmly and leave", "Try it once", "Say maybe"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 2.1: Alcohol, Tobacco, Vaping and Drugs$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{3,1,3,1}'::int[], array[$j$Federal and Florida law set the age at twenty one.$j$,$j$Nicotine affects teen brain development.$j$,$j$Counterfeit pills can be deadly.$j$,$j$A clear no with a plan protects you.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 2.1: Alcohol, Tobacco, Vaping and Drugs$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 7, $j$Check 2.2: Disease Prevention and Immunity$j$, $j${"questions": [{"q": "A communicable disease is one that:", "options": ["Spreads from person to person", "Cannot be treated", "Is never serious", "Only affects adults"]}, {"q": "Antibiotics work against:", "options": ["Colds and flu", "Bacterial infections", "Allergies", "All viruses"]}, {"q": "Vaccines help the body by:", "options": ["Training the immune system to recognize a germ", "Curing every illness", "Stopping sleep", "Replacing food"]}, {"q": "Which is a noncommunicable disease?", "options": ["Diabetes", "A cold", "The flu", "Strep throat"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 2.2: Disease Prevention and Immunity$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{0,1,0,0}'::int[], array[$j$Communicable diseases are spread by germs.$j$,$j$They do not work on viruses.$j$,$j$Vaccines prepare the immune system.$j$,$j$Diabetes does not spread from person to person.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 2.2: Disease Prevention and Immunity$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 8, $j$Check 2.3: Safety, Injury Prevention and First Aid$j$, $j${"questions": [{"q": "What number do you call in an emergency?", "options": ["311", "211", "911", "511"]}, {"q": "Hands only CPR compressions are about:", "options": ["60 per minute", "100 to 120 per minute", "200 per minute", "20 per minute"]}, {"q": "For heavy bleeding, you should:", "options": ["Apply no pressure", "Ignore it", "Remove the cloth often", "Apply firm direct pressure with a clean cloth"]}, {"q": "An AED is used to:", "options": ["Treat a cold", "Restart a normal heart rhythm with a shock when needed", "Stop bleeding", "Cool a burn"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 2.3: Safety, Injury Prevention and First Aid$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{2,1,3,1}'::int[], array[$j$911 reaches emergency services.$j$,$j$Push hard and fast at that rate.$j$,$j$Direct pressure slows bleeding.$j$,$j$AEDs give voice prompts and deliver a shock when needed.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 2.3: Safety, Injury Prevention and First Aid$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 9, $j$Check 2.4: Violence, Bullying and Online Safety$j$, $j${"questions": [{"q": "Cyberbullying is bullying that happens:", "options": ["Only in person", "Through phones and the internet", "Only at school", "Only at night"]}, {"q": "An upstander:", "options": ["Spreads the post", "Stands with the person and reports bullying", "Watches silently", "Joins in"]}, {"q": "Which is a warning sign of dating violence?", "options": ["Honest talk", "Respecting your friends", "Kind words", "Jealousy, isolating you and checking your phone"]}, {"q": "If a stranger pressures you online, you should:", "options": ["Send personal pictures", "Share your address", "Report it to a trusted adult", "Meet them"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 2.4: Violence, Bullying and Online Safety$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{1,1,3,2}'::int[], array[$j$Online harassment is cyberbullying.$j$,$j$Upstanders support others and report.$j$,$j$Control is a warning sign.$j$,$j$Tell a trusted adult right away.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 2.4: Violence, Bullying and Online Safety$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 10, $j$Unit Quiz 2: Risk and Prevention$j$, $j${"questions": [{"q": "Which is illegal for anyone under twenty one in Florida?", "options": ["Buying alcohol", "Drinking water", "Sleeping", "Eating vegetables"]}, {"q": "Nicotine can harm teens by affecting the:", "options": ["Hair color", "Eye color", "Developing brain", "Height only"]}, {"q": "Pills from a friend might contain:", "options": ["Fentanyl", "Only vitamins", "Only sugar", "Nothing"]}, {"q": "A vaccine works by:", "options": ["Replacing sleep", "Stopping bleeding", "Training the immune system", "Cooling a burn"]}, {"q": "Antibiotics treat:", "options": ["Bacterial infections", "All viruses", "Flu", "Colds"]}, {"q": "Hands only CPR begins with:", "options": ["Waiting", "Shaking the person", "Giving water", "Calling 911 then pushing hard and fast in the center of the chest"]}, {"q": "A cyberbully uses:", "options": ["Only notes", "Phones and the internet to hurt others", "Only voice calls", "Only fists"]}, {"q": "A warning sign of an unhealthy relationship is:", "options": ["Trust", "Jealous control and threats", "Honesty", "Respect"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Unit Quiz 2: Risk and Prevention$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{0,2,0,2,0,3,1,1}'::int[], array[$j$The legal age for alcohol is twenty one.$j$,$j$Nicotine affects attention, learning and mood.$j$,$j$Counterfeit pills are deadly.$j$,$j$It prepares the body to recognize a germ.$j$,$j$They are not for viruses.$j$,$j$Call 911 and start compressions.$j$,$j$Cyberbullying happens online.$j$,$j$Control and threats are not love.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Unit Quiz 2: Risk and Prevention$j$ on conflict (item_id) do nothing;
